-- Contratos: prazos de entrega (DRE/Fluxo até o dia 10, condicionada ao cliente),
-- retorno de pendências em 24h, fluxo depende de lançamentos/conciliações, serviços
-- adicionais só com autorização prévia e rescisão SEM multa com aviso de 30 dias
-- (mensalidade proporcional durante o aviso). Espelha src/data/clausulasSeed.js.

insert into cci_clausulas (chave, titulo, tipo, obrigatoria, condicao, ordem, revisar_juridico, variaveis, corpo, ativo)
values ('geral_prazos_entregas', 'Dos Prazos, das Entregas e das Condições de Execução', 'geral', true, $j${"modo": "sempre"}$j$::jsonb, 68, false, array['entregas.diaRelatorios','entregas.prazoRetorno']::text[], $j$[{"tipo": "subtitulo", "texto": "Entrega dos relatórios mensais"}, {"tipo": "paragrafo", "texto": "A CONTRATADA entregará os relatórios mensais de Demonstração do Resultado do Exercício (DRE) e de Fluxo de Caixa até o dia {{entregas.diaRelatorios}} do mês subsequente ao da competência a que se referem."}, {"tipo": "paragrafo", "texto": "A entrega dos relatórios de DRE e de Fluxo de Caixa no prazo acima está condicionada à execução prévia, completa e tempestiva, pela equipe da CONTRATANTE, dos trabalhos sob sua responsabilidade, tais como o envio de documentos, os lançamentos, os fechamentos de caixa e o retorno às pendências apontadas. Não executados esses trabalhos no tempo devido, o prazo de entrega fica prorrogado pelo mesmo período do atraso, sem que isso caracterize descumprimento contratual pela CONTRATADA."}, {"tipo": "subtitulo", "texto": "Retorno de dúvidas e inconsistências"}, {"tipo": "paragrafo", "texto": "A CONTRATANTE deverá responder às dúvidas e às inconsistências identificadas e comunicadas pela CONTRATADA, pelos canais definidos entre as partes, no prazo máximo de {{entregas.prazoRetorno}}, contado do envio da comunicação. O retorno fora desse prazo prorroga, na mesma proporção, os prazos de entrega a cargo da CONTRATADA que dele dependam."}, {"tipo": "subtitulo", "texto": "Acompanhamento do Fluxo de Caixa"}, {"tipo": "paragrafo", "texto": "O acompanhamento do Fluxo de Caixa somente poderá ser realizado mediante a realização correta e tempestiva dos lançamentos e das conciliações. A CONTRATADA não responde por divergências, atrasos ou imprecisões do Fluxo de Caixa decorrentes de lançamentos ou conciliações não realizados, incompletos ou incorretos sob a responsabilidade da CONTRATANTE."}]$j$::jsonb, true)
on conflict (chave) do update set titulo = excluded.titulo, corpo = excluded.corpo, variaveis = excluded.variaveis, ordem = excluded.ordem;

insert into cci_clausulas (chave, titulo, tipo, obrigatoria, condicao, ordem, revisar_juridico, variaveis, corpo, ativo)
values ('geral_servicos_adicionais', 'Dos Serviços Adicionais', 'geral', true, $j${"modo": "sempre"}$j$::jsonb, 72, false, '{}'::text[], $j$[{"tipo": "paragrafo", "texto": "Os serviços não compreendidos no escopo deste contrato somente serão executados mediante autorização prévia e expressa da CONTRATANTE, por escrito (inclusive por e-mail ou aplicativo de mensagens), após a apresentação, pela CONTRATADA, do respectivo escopo, valor e prazo de execução."}, {"tipo": "paragrafo", "texto": "Nenhum serviço adicional será executado ou cobrado sem a autorização prévia de que trata esta cláusula. Os serviços adicionais autorizados serão cobrados conforme o valor aprovado, juntamente com a mensalidade subsequente à sua execução, salvo condição diversa acordada."}]$j$::jsonb, true)
on conflict (chave) do update set titulo = excluded.titulo, corpo = excluded.corpo, variaveis = excluded.variaveis, ordem = excluded.ordem;

update cci_clausulas set variaveis = array['rescisao.avisoPrevio']::text[], corpo = $j$[{"tipo": "paragrafo", "texto": "Qualquer das partes poderá cancelar este contrato a qualquer tempo, sem incidência de multa, mediante aviso prévio por escrito de {{rescisao.avisoPrevio}}."}, {"tipo": "paragrafo", "texto": "Durante o período de aviso prévio, os serviços continuarão a ser prestados normalmente e a mensalidade continuará sendo cobrada, de forma proporcional aos dias do aviso que recaírem em cada mês, nas mesmas condições de pagamento deste contrato."}, {"tipo": "paragrafo", "texto": "O contrato poderá ser rescindido de pleno direito, independentemente de aviso, em caso de descumprimento de obrigação essencial não sanada no prazo concedido pela parte prejudicada."}, {"tipo": "paragrafo", "texto": "O encerramento não afasta as obrigações pendentes até a data do término, especialmente o pagamento dos serviços já prestados e a devolução ou eliminação de informações na forma acordada."}]$j$::jsonb
 where chave = 'geral_rescisao';

-- A multa saiu do contrato: limpa a descrição antiga da config para não confundir.
update cci_config_empresa set regras = jsonb_set(regras, '{rescisao}', (coalesce(regras->'rescisao', '{}'::jsonb) - 'multa_descricao'))
 where regras ? 'rescisao';
